import { config } from './config';
import type { MoneyCurrency } from './money';
import { fetchWhileWaking } from './wake';

/**
 * Public link of a Venta (issue #35). The token lives in `order_share` (generated by Postgres) and the
 * public page asks Hapi `GET /public/orders/{token}` for a curated DTO; Hasura has no anonymous access.
 */

/** Same format Hapi validates (24 random bytes as hex). */
const SHARE_TOKEN_PATTERN = /^[0-9a-f]{48}$/;

export function isShareToken(token: string | null | undefined): token is string {
  return typeof token === 'string' && SHARE_TOKEN_PATTERN.test(token);
}

/** Absolute URL of the public page, e.g. `https://angelocg97.github.io/conkora-admin-system/venta/?t=…`. */
export function shareUrl(origin: string, basePath: string, token: string): string {
  return `${origin}${basePath}/venta/?t=${encodeURIComponent(token)}`;
}

/** DTO from `backend/src/public/order-dto.ts` (keep in sync). */
export interface PublicOrder {
  customerName: string;
  date: string;
  status: string;
  statusLabel: string;
  tripName: string | null;
  currency: MoneyCurrency;
  items: {
    name: string;
    size: string | null;
    quantity: number;
    price: number;
    lineTotal: number;
    lineTotalUsd: number;
    lineTotalCrc: number;
    photoUrl: string | null;
  }[];
  payments: {
    date: string;
    amount: number;
    currency: MoneyCurrency;
    orderAmount: number;
    amountUsd: number;
    amountCrc: number;
  }[];
  totals: {
    total: number;
    totalUsd: number;
    totalCrc: number;
    paid: number;
    paidUsd: number;
    paidCrc: number;
    balance: number;
    balanceUsd: number;
    balanceCrc: number;
  };
}

export type ShareOutcome = 'shared' | 'copied' | 'cancelled' | 'failed';

type ShareNavigator = {
  share?: (data: ShareData) => Promise<void>;
  clipboard?: { writeText(text: string): Promise<void> };
};

/**
 * Opens the device's share sheet (Web Share API) or, where there is none, copies the URL to the clipboard.
 * Closing the share sheet (AbortError) is `cancelled`, not an error. Pass `navigator`.
 */
export async function shareLink(nav: ShareNavigator, data: { title: string; text: string; url: string }): Promise<ShareOutcome> {
  if (typeof nav.share === 'function') {
    try {
      await nav.share(data);
      return 'shared';
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') return 'cancelled';
      // NotAllowedError (e.g. the user gesture expired) and others: fall back to the clipboard.
    }
  }
  try {
    if (!nav.clipboard) return 'failed';
    await nav.clipboard.writeText(data.url);
    return 'copied';
  } catch {
    return 'failed';
  }
}

export type PublicOrderResult =
  | { kind: 'ok'; order: PublicOrder }
  | { kind: 'not-found' }
  | { kind: 'rate-limited' }
  | { kind: 'error' };

/** Loads the public page's data, retrying while Render wakes the API up (`onWaking` on each retry). */
export async function fetchPublicOrder(token: string, { onWaking }: { onWaking?: () => void } = {}): Promise<PublicOrderResult> {
  if (!isShareToken(token)) return { kind: 'not-found' };
  let response: Response;
  try {
    response = await fetchWhileWaking(
      (signal) =>
        fetch(`${config.apiUrl}/public/orders/${encodeURIComponent(token)}`, {
          cache: 'no-store',
          credentials: 'omit',
          referrerPolicy: 'no-referrer',
          signal,
        }),
      { onRetry: onWaking },
    );
  } catch {
    return { kind: 'error' };
  }
  if (response.status === 404) return { kind: 'not-found' };
  if (response.status === 429) return { kind: 'rate-limited' };
  if (!response.ok) return { kind: 'error' };
  try {
    return { kind: 'ok', order: (await response.json()) as PublicOrder };
  } catch {
    return { kind: 'error' };
  }
}
